var count = 0;

var udpLadderSocket;
var UDP_LADDER_SOCKET_PORT=5555;
var currentLadderLogic = null;
var LADDER_LOGIC_INTERPRETER;

function setup() {

	resetOutputs();
	CLI.setup();
	//GUI.setup();
	LADDER_LOGIC_INTERPRETER = new LadderLogicInterpreter();
	udpLadderSocket = new UDPSocket();
	udpLadderSocket.onReceive = onLadderLogicReceived;
	udpLadderSocket.begin(UDP_LADDER_SOCKET_PORT);

	try{
		deserializeEvent();

		//Serial.println("PLC Started with Ladder Logic:");
		//Serial.println(JSON.stringify(currentLadderLogic));


	}
	catch(e)
	{
		Serial.println(e);
	}

}

function resetOutputs()
{
	analogWrite(A0, 0);
	analogWrite(A1, 0);
	analogWrite(A2, 0);
	analogWrite(A3, 0);


	for(var i=0; i<6; i++)
	{
		try{
			digitalWrite(i, 0);

		}catch(e)
		{
			Serial.println(e)
		}
	}
}


function readInputs()
{
	for(var i=0; i<currentLadderLogic.tags.length; i++)
	{
		try{
			var t = currentLadderLogic.tags[i];
			if (t.ioDirection === "input" )
			{
				if ( t.address && t.address.indexOf("D") === 0)
				{
					var terminal = t.address.substring(1, t.address.length);
					t.value = digitalRead(terminal);


					LADDER_LOGIC_INTERPRETER.setInput(t.name, t.value);





				}
				else if ( t.address && t.address.indexOf("A") === 0)
				{
					var digitalPorts = 6;
					var analogAddress = parseInt(t.address.substring(1, t.address.length))+digitalPorts;

					t.value = analogRead(analogAddress);
					LADDER_LOGIC_INTERPRETER.setInput(t.name, t.value);

				}


			//	Serial.println("INPUT: " + t.name + ": " + t.value);
			}
		}
		catch(e)
		{
			Serial.println(e);
		}
	}
}


function setOutputs()
{
	var value = 0;
	for(var i=0; i<currentLadderLogic.tags.length; i++)
	{
		try
		{
			var t = currentLadderLogic.tags[i];
			if (t.ioDirection === "output" )
			{
				value = LADDER_LOGIC_INTERPRETER.getOutput(t.name);
				//Serial.println(t.name + ": " + t.address + " "  + value);

				if ( t.address && t.address.indexOf("D") === 0)
				{
					digitalWrite(t.address.substring(1, t.address.length), value*HIGH);
				}
				else if ( t.address && t.address.indexOf("A") === 0)
				{
					var digitalPorts = 6;
					var analogAddress = parseInt(t.address.substring(1, t.address.length))+digitalPorts;

					analogWrite(analogAddress, value);
				}
			}			

		}catch(e)
		{
			Serial.println(e);
		}
	}

}



function loop()
{
	delay(100);
	if ( currentLadderLogic === null )
		return;
	try{
		// set inputs
		readInputs();

		// evaluate ladder
		LADDER_LOGIC_INTERPRETER.evaluateLadder();

		//Serial.println(LADDER_LOGIC_INTERPRETER.getStates())
		// set outputs
		setOutputs();
	}catch(e)
	{
		Serial.println(e)
	}
}


function onLadderLogicReceived(ip, port, data)
{
	try{
		data = JSON.parse(data);
		if ( data.command === "SET_LADDER_LOGIC")
		{

			currentLadderLogic = data.payload;

			Serial.println("set ladder logic: " + JSON.stringify(currentLadderLogic))
			LADDER_LOGIC_INTERPRETER.download(JSON.stringify(currentLadderLogic));

			resetOutputs();

			serializeEvent()
		}
		else if ( data.command === "FIRMWARE_UPDATE")
		{
			var payloadStr = Base64.decode(data.payload);
			Serial.println(payloadStr);
			var firmware = JSON.parse(payloadStr);

			var payload = {
					command:"FIRMWARE_UPDATE_FAILED",
			};
			if ( firmware.model == "PLC-PT" && firmware.version )
			{
				setDeviceProperty(getName(), "PT_VERSION", firmware.version )
				payload.command = "FIRMWARE_UPDATE_SUCCESSFUL";
			}

			udpLadderSocket.send(ip, port, JSON.stringify(payload));

		}
	}catch(e)
	{
		Serial.println(e);
	}
}




function serializeEvent()
{
	try{
		if ( currentLadderLogic === null )
			return;

		var f = FileSystem.open("/ladder.json", File.WRITE);
		f.println(JSON.stringify(currentLadderLogic));
		f.close();
	} catch(e)
	{
		Serial.println("ERROR: serialize failed")
		Serial.println(currentLadderLogic);
	}
}


function deserializeEvent()
{
	try{
		if ( !FileSystem.exists("/ladder.json"))
			return;
		var f = FileSystem.open("/ladder.json", File.READ);

		var dataStr = f.readln();

		currentLadderLogic = JSON.parse(dataStr);

		Serial.println(dataStr);
		Serial.println(LADDER_LOGIC_INTERPRETER.download(dataStr));
		/*
		Serial.println(LADDER_LOGIC_INTERPRETER.getStates());
		LADDER_LOGIC_INTERPRETER.setInput("start", 1);
		LADDER_LOGIC_INTERPRETER.evaluateLadder();
		Serial.println(LADDER_LOGIC_INTERPRETER.getStates());

		LADDER_LOGIC_INTERPRETER.setInput("start", 0);
		LADDER_LOGIC_INTERPRETER.evaluateLadder();
		Serial.println(LADDER_LOGIC_INTERPRETER.getStates());

		LADDER_LOGIC_INTERPRETER.setInput("start", 1);
		LADDER_LOGIC_INTERPRETER.evaluateLadder();
		Serial.println(LADDER_LOGIC_INTERPRETER.getStates());
		*/

	} catch(e)
	{
		Serial.println("ERROR: deserialize failed.")
		Serial.println(e);
		//Serial.println(currentLadderLogic);
	}
}

function onLoad() {
	guiEvent('onLoad');
}

function action() {
	guiEvent('click', 'some arg');
}

